  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  ServerMessage,
 55→  ServerMessageHistory,
 56→  ServerTaskList,
 57→  ServerTaskUpdated,
 58→  ServerTaskDeleted,
 59→  Task,
 60→  TaskPriority,
 61→  ToolCallInfo,
 62→  UserQuestion,
 63→} from "@/lib/types";
 64→
 65→/** Connect to the WS server on the same host the page was loaded from. */
 66→const WS_URL =
 67→  typeof window !== "undefined"
 68→    ? `ws://${window.location.hostname}:9900/browser`
 69→    : "ws://localhost:9900/browser";
 70→
 71→/** Per-agent client state. */
 72→export interface AgentClientState {
 73→  status: AgentStatus;
 74→  messages: ChatMessage[];
 75→  /** Raw Claude NDJSON messages for debug view. */
 76→  rawMessages: ClaudeMessage[];
 77→  label: string;
 78→  tmuxSession: string | null;
 79→  createdAt: number;
 80→}
 81→
 82→/**
 83→ * Extract displayable text from a Claude assistant message.
 84→ * Content blocks may be text, tool_use, or tool_result — each is
 85→ * handled defensively since the array structure can vary.
 86→ */
 87→function extractText(msg: ClaudeAssistant): string {
 88→  const blocks = msg.message?.content;
 89→  if (!blocks || !Array.isArray(blocks)) return "";
 90→  return blocks
 91→    .map((b) => {
 92→      if (b.type === "text") return b.text;
 93→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 94→      if (b.type === "tool_result") {
 95→        const c = (b as { content?: unknown }).content;
 96→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 97→      }
 98→      return "";
 99→    })
100→    .filter(Boolean)
101→    .join("\n");
102→}
103→
104→/** Module-level counter for generating unique message IDs. */
105→let msgCounter = 0;
106→function nextId() {
107→  return `msg-${Date.now()}-${++msgCounter}`;
108→}
109→
110→/**
111→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
112→ * Used both for live messages and for replaying message_history.
113→ */
114→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
115→  if (relayMsg.type === "relay") {
116→    const msg = relayMsg.message;
117→
118→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
119→      const init = msg as ClaudeSystemInit;
120→      return {
121→        id: nextId(),
122→        role: "system",
123→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
124→        timestamp: Date.now(),
125→      };
126→    }
127→
128→    if (msg.type === "user") {
129→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
130→      // Only render human-typed user messages (string content).
131→      // CLI tool_result messages have array content — these are internal
132→      // protocol messages and are only visible in the raw message viewer.
133→      if (typeof rawContent !== "string") return null;
134→      if (!rawContent.trim()) return null;
135→      return {
136→        id: nextId(),
137→        role: "user",
138→        content: rawContent,
139→        timestamp: Date.now(),
140→      };
141→    }
142→
143→    if (msg.type === "assistant") {
144→      const assistant = msg as ClaudeAssistant;
145→      const text = extractText(assistant);
146→      if (!text) return null;
147→
148→      const blocks = assistant.message?.content ?? [];
149→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
150→      const toolCalls: ToolCallInfo[] = blocks
151→        .filter((b) => b.type === "tool_use")
152→        .map((b) => ({
153→          name: (b as { name: string }).name,
154→          toolUseId: (b as { id: string }).id,
155→        }));
156→      const isToolOnly = !hasText && toolCalls.length > 0;
157→
158→      return {
159→        id: nextId(),
160→        role: "assistant",
161→        content: text,
162→        timestamp: Date.now(),
163→        toolCalls,
164→        isToolOnly,
165→      };
166→    }
167→
168→    if (msg.type === "result") {
169→      const result = msg as ClaudeResult;
170→      const summary = result.is_error
171→        ? `Error: ${result.error}`
172→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
173→      return {
174→        id: nextId(),
175→        role: "system",
176→        content: summary,
177→        timestamp: Date.now(),
178→      };
179→    }
180→
181→    if (msg.type === "control_request") {
182→      const cr = msg as ClaudeControlRequest;
183→
184→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
185→      if (cr.request.tool_name === "AskUserQuestion") {
186→        const input = cr.request.input as { questions?: UserQuestion[] };
187→        const questions = Array.isArray(input.questions) ? input.questions : [];
188→        return {
189→          id: nextId(),
190→          role: "system",
191→          content: "Question from Claude",
192→          timestamp: Date.now(),
193→          userQuestion: {
194→            requestId: cr.request_id,
195→            questions,
196→          },
197→        };
198→      }
199→
200→      return {
201→        id: nextId(),
202→        role: "system",
203→        content: `Tool approval requested: ${cr.request.tool_name}`,
204→        timestamp: Date.now(),
205→        controlRequest: {
206→          id: cr.request_id,
207→          tool_name: cr.request.tool_name,
208→          input: cr.request.input,
209→          description: cr.request.description,
210→        },
211→      };
212→    }
213→  }
214→
215→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
216→    return {
217→      id: nextId(),
218→      role: "system",
219→      content: `Error: ${relayMsg.error}`,
220→      timestamp: Date.now(),
221→    };
222→  }
223→
224→  return null;
225→}
226→
227→/** Console logger with [thos] prefix for easy filtering. */
228→function log(...args: unknown[]) {
229→  console.log("[thos-ws]", ...args);
230→}
231→
232→export function useWebSocket() {
233→  const wsRef = useRef<WebSocket | null>(null);
234→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
235→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
236→  const closingRef = useRef(false);
237→  const [connected, setConnected] = useState(false);
238→  /** True once we've received the initial agent_list from the server. */
239→  const [initialLoadDone, setInitialLoadDone] = useState(false);
240→
241→  // Multi-agent state
242→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
243→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
244→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
245→
246→  // Task state
247→  const [tasks, setTasks] = useState<Task[]>([]);
248→
249→  // Per-agent deduplication: track count of processed messages per agent
250→  // to avoid duplicating messages already in local state during history replay.
251→  const processedCountRef = useRef<Map<string, number>>(new Map());
252→
253→  // Track which agents have had their history loaded (lazy loading).
254→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
255→
256→  /** Immutably update a single agent's state in the Map. */
257→  const updateAgent = useCallback(
258→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
259→      setAgents((prev) => {
260→        const existing = prev.get(agentId);
261→        if (!existing) return prev;
262→        const next = new Map(prev);
263→        next.set(agentId, updater(existing));
264→        return next;
265→      });
266→    },
267→    []
268→  );
269→
270→  const connect = useCallback(() => {
271→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
272→    if (wsRef.current) {
273→      wsRef.current.close();
274→      wsRef.current = null;
275→    }
276→
277→    // Reset dedup counts on new connection — server will send fresh history
278→    processedCountRef.current.clear();
279→    setInitialLoadDone(false);
280→    setLoadedAgents(new Set());
281→
282→    log("connecting to", WS_URL);
283→    const ws = new WebSocket(WS_URL);
284→    wsRef.current = ws;
285→
286→    ws.onopen = () => {
287→      log("connected");
288→      setConnected(true);
289→    };
290→
291→    ws.onclose = () => {
292→      log("disconnected, closingRef =", closingRef.current);
293→      setConnected(false);
294→      wsRef.current = null;
295→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
296→      if (closingRef.current) return;
297→      // Reconnection guard: clear any existing timer before scheduling
298→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
299→      log("scheduling reconnect in 2s");
300→      reconnectTimer.current = setTimeout(() => connect(), 2000);
301→    };
302→
303→    ws.onerror = (e) => {
304→      log("error", e);
305→      // onclose will fire after onerror, which triggers reconnect
306→    };
307→
308→    ws.onmessage = (event) => {
309→      let data: ServerMessage;
310→      try {
311→        data = JSON.parse(event.data as string);
312→      } catch {
313→        return;
314→      }
315→
316→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
317→
318→      // ── task_list: full task list from server ──
319→      if (data.type === "task_list") {
320→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
321→        setTasks((data as ServerTaskList).tasks);
322→        return;
323→      }
324→
325→      // ── task_updated: single task changed ──
326→      if (data.type === "task_updated") {
327→        const updated = (data as ServerTaskUpdated).task;
328→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
329→        return;
330→      }
331→
332→      // ── task_deleted: remove task ──
333→      if (data.type === "task_deleted") {
334→        const deletedId = (data as ServerTaskDeleted).taskId;
335→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
336→        return;
337→      }
338→
339→      // ── message_history: replay full history from server ──
340→      if (data.type === "message_history") {
341→        const historyMsg = data as ServerMessageHistory;
342→        const agentId = historyMsg.agentId;
343→        const serverMessages = historyMsg.messages;
344→        log("message_history:", agentId, serverMessages.length, "raw msgs");
345→
346→        // Convert all server messages to ChatMessages + extract raw Claude messages
347→        const chatMessages: ChatMessage[] = [];
348→        const rawMessages: ClaudeMessage[] = [];
349→        for (const sm of serverMessages) {
350→          if (sm.type === "relay") {
351→            rawMessages.push(sm.message);
352→          }
353→          const cm = relayChatMessage(agentId, sm);
354→          if (cm) chatMessages.push(cm);
355→        }
356→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
357→
358→        // Always replace local messages with server history (source of truth).
359→        setAgents((prev) => {
360→          const existing = prev.get(agentId);
361→          if (!existing) {
362→            log("message_history:", agentId, "agent not in map yet, creating");
363→            const next = new Map(prev);
364→            next.set(agentId, {
365→              status: "idle",
366→              messages: chatMessages,
367→              rawMessages,
368→              label: "",
369→              tmuxSession: null,
370→              createdAt: 0,
371→            });
372→            return next;
373→          }
374→          const next = new Map(prev);
375→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
376→          return next;
377→        });
378→
379→        processedCountRef.current.set(agentId, chatMessages.length);
380→        setLoadedAgents((prev) => {
381→          if (prev.has(agentId)) return prev;
382→          const next = new Set(prev);
383→          next.add(agentId);
384→          return next;
385→        });
386→        return;
387→      }
388→
389→      // ── history_cleared: wipe local messages for this agent ──
390→      if (data.type === "history_cleared") {
391→        updateAgent(data.agentId, (prev) => ({
392→          ...prev,
393→          messages: [],
394→          rawMessages: [],
395→        }));
396→        processedCountRef.current.set(data.agentId, 0);
397→        return;
398→      }
399→
400→      // ── cli_disconnected: show system message ──
401→      if (data.type === "cli_disconnected") {
402→        updateAgent(data.agentId, (prev) => ({
403→          ...prev,
404→          messages: [
405→            ...prev.messages,
406→            {
407→              id: nextId(),
408→              role: "system",
409→              content: "CLI session ended",
410→              timestamp: Date.now(),
411→            },
412→          ],
413→        }));
414→        return;
415→      }
416→
417→      // ── cli_connected: show system message ──
418→      if (data.type === "cli_connected") {
419→        updateAgent(data.agentId, (prev) => {
420→          const isReconnect = prev.messages.length > 0;
421→          return {
422→            ...prev,
423→            messages: [
424→              ...prev.messages,
425→              {
426→                id: nextId(),
427→                role: "system",
428→                content: isReconnect ? "CLI reconnected" : "CLI connected",
429→                timestamp: Date.now(),
430→              },
431→            ],
432→          };
433→        });
434→        return;
435→      }
436→
437→      // ── agent_list: reconcile sidebar state from server ──
438→      if (data.type === "agent_list") {
439→        const serverAgents = data.agents as AgentInfo[];
440→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
441→        setAgents((prev) => {
442→          const next = new Map(prev);
443→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
444→
445→          // Update or add agents from server
446→          for (const info of serverAgents) {
447→            const existing = next.get(info.agentId);
448→            if (existing) {
449→              next.set(info.agentId, {
450→                ...existing,
451→                status: info.status,
452→                tmuxSession: info.tmuxSession,
453→                label: info.label,
454→              });
455→            } else {
456→              next.set(info.agentId, {
457→                status: info.status,
458→                messages: [],
459→                rawMessages: [],
460→                label: info.label,
461→                tmuxSession: info.tmuxSession,
462→                createdAt: info.createdAt,
463→              });
464→            }
465→          }
466→
467→          // Remove agents no longer on the server
468→          for (const id of next.keys()) {
469→            if (!serverIds.has(id)) {
470→              next.delete(id);
471→            }
472→          }
473→
474→          return next;
475→        });
476→        setAgentOrder(serverAgents.map((a) => a.agentId));
477→        setInitialLoadDone(true);
478→
479→        // Auto-select the first agent on initial load when nothing is selected
480→        setActiveAgentId((prev) => {
481→          if (prev !== null) return prev;
482→          if (serverAgents.length === 0) return null;
483→          return serverAgents[0].agentId;
484→        });
485→        return;
486→      }
487→
488→      // ── spawned: auto-select the newly created agent ──
489→      if (data.type === "spawned") {
490→        setActiveAgentId(data.agentId);
491→        return;
492→      }
493→
494→      // ── status: update a specific agent's status ──
495→      if (data.type === "status") {
496→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
497→        return;
498→      }
499→
500→      // ── error: append to agent's message list ──
501→      if (data.type === "error") {
502→        updateAgent(data.agentId, (prev) => ({
503→          ...prev,
504→          messages: [
505→            ...prev.messages,
506→            {
507→              id: nextId(),
508→              role: "system",
509→              content: `Error: ${data.error}`,
510→              timestamp: Date.now(),
511→            },
512→          ],
513→        }));
514→        // Track processed count for dedup
515→        processedCountRef.current.set(
516→          data.agentId,
517→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
518→        );
519→        return;
520→      }
521→
522→      // ── relay: append claude message to agent's history ──
523→      if (data.type === "relay") {
524→        const agentId = data.agentId;
525→        const rawMsg = data.message;
526→        const chatMsg = relayChatMessage(agentId, data);
527→
528→        updateAgent(agentId, (prev) => ({
529→          ...prev,
530→          rawMessages: [...prev.rawMessages, rawMsg],
531→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
532→        }));
533→        if (chatMsg) {
534→          // Track processed count for dedup
535→          processedCountRef.current.set(
536→            agentId,
537→            (processedCountRef.current.get(agentId) ?? 0) + 1
538→          );
539→        }
540→        return;
541→      }
542→    };
543→  }, [updateAgent]);
544→
545→  useEffect(() => {
546→    closingRef.current = false;
547→    connect();
548→    return () => {
549→      closingRef.current = true;
550→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
551→      wsRef.current?.close();
552→    };
553→  }, [connect]);
554→
555→  const send = useCallback((data: object) => {
556→    if (wsRef.current?.readyState === WebSocket.OPEN) {
557→      wsRef.current.send(JSON.stringify(data));
558→    }
559→  }, []);
560→
561→  // Request history for the active agent if not already loaded.
562→  useEffect(() => {
563→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
564→    log("requesting history for", activeAgentId);
565→    send({ type: "request_history", agentId: activeAgentId });
566→  }, [activeAgentId, loadedAgents, send]);
567→
568→  const spawnAgent = useCallback(
569→    (prompt: string) => {
570→      send({ type: "spawn", prompt });
571→    },
572→    [send]
573→  );
574→
575→  const sendMessage = useCallback(
576→    (content: string) => {
577→      if (!activeAgentId) return;
578→      // Optimistically add user message to local state
579→      updateAgent(activeAgentId, (prev) => ({
580→        ...prev,
581→        messages: [
582→          ...prev.messages,
583→          {
584→            id: nextId(),
585→            role: "user",
586→            content,
587→            timestamp: Date.now(),
588→          },
589→        ],
590→      }));
591→      send({ type: "send_message", agentId: activeAgentId, content });
592→    },
593→    [send, activeAgentId, updateAgent]
594→  );
595→
596→  const respondToControl = useCallback(
597→    (requestId: string, allow: boolean) => {
598→      if (!activeAgentId) return;
599→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
600→      updateAgent(activeAgentId, (prev) => ({
601→        ...prev,
602→        messages: prev.messages.map((m) =>
603→          m.controlRequest?.id === requestId
604→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
605→            : m
606→        ),
607→      }));
608→    },
609→    [send, activeAgentId, updateAgent]
610→  );
611→
612→  /** Respond to an AskUserQuestion control request with the user's selections. */
613→  const respondToUserQuestion = useCallback(
614→    (requestId: string, answers: Record<string, string>) => {
615→      if (!activeAgentId) return;
616→      send({
617→        type: "control_response",
618→        agentId: activeAgentId,
619→        request_id: requestId,
620→        allow: true,
621→        answers,
622→      });
623→      updateAgent(activeAgentId, (prev) => ({
624→        ...prev,
625→        messages: prev.messages.map((m) =>
626→          m.userQuestion?.requestId === requestId
627→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
628→            : m
629→        ),
630→      }));
631→    },
632→    [send, activeAgentId, updateAgent]
633→  );
634→
635→  // ── Agent management actions ──────────────────────────────────────────────
636→
637→  const killAgent = useCallback(
638→    (agentId: string) => {
639→      send({ type: "kill_agent", agentId });
640→    },
641→    [send]
642→  );
643→
644→  const deleteAgent = useCallback(
645→    (agentId: string) => {
646→      send({ type: "delete_agent", agentId });
647→      // Deselect if we just deleted the active agent
648→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
649→    },
650→    [send]
651→  );
652→
653→  const renameAgent = useCallback(
654→    (agentId: string, label: string) => {
655→      send({ type: "rename_agent", agentId, label });
656→    },
657→    [send]
658→  );
659→
660→  const clearHistory = useCallback(
661→    (agentId: string) => {
662→      send({ type: "clear_history", agentId });
663→    },
664→    [send]
665→  );
666→
667→  // ── Task actions ──────────────────────────────────────────────────────────
668→
669→  const createTask = useCallback(
670→    (title: string, description: string, priority: TaskPriority) => {
671→      send({ type: "create_task", title, description, priority });
672→    },
673→    [send]
674→  );
675→
676→  const updateTask = useCallback(
677→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
678→      send({ type: "update_task", taskId, updates });
679→    },
680→    [send]
681→  );
682→
683→  const deleteTask = useCallback(
684→    (taskId: string) => {
685→      send({ type: "delete_task", taskId });
686→    },
687→    [send]
688→  );
689→
690→  const delegateTask = useCallback(
691→    (taskId: string) => {
692→      send({ type: "delegate_task", taskId });
693→    },
694→    [send]
695→  );
696→
697→  // Derived values for the active agent
698→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
699→  const activeStatus = useMemo<AgentStatus>(
700→    () => activeAgent?.status ?? "idle",
701→    [activeAgent?.status]
702→  );
703→  const activeMessages = useMemo<ChatMessage[]>(
704→    () => activeAgent?.messages ?? [],
705→    [activeAgent?.messages]
706→  );
707→  const activeRawMessages = useMemo<ClaudeMessage[]>(
708→    () => activeAgent?.rawMessages ?? [],
709→    [activeAgent?.rawMessages]
710→  );
711→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
712→
713→  return {
714→    connected,
715→    initialLoadDone,
716→    historyLoading,
717→    agents,
718→    agentOrder,
719→    activeAgentId,
720→    setActiveAgentId,
721→    activeStatus,
